// Responsibility: Manages spatial distortion fields that teleport coins to random bumpers upon collision. // Attachment Note: Attach to a Trigger Collider volume to create a teleporting pinball nightmare. using UnityEngine; public class GravityInversionField : MonoBehaviour { private void OnTriggerEnter(Collider other) { if (other.CompareTag("Coin")) { Rigidbody rb = other.GetComponent<Rigidbody>(); if (rb != null) { rb.useGravity = false; rb.AddForce(Vector3.up * 20f, ForceMode.Impulse); } DistortSpatialPosition(other.transform); } } private void DistortSpatialPosition(Transform coinTransform) { GameObject[] bumpers = GameObject.FindGameObjectsWithTag("Bumper"); if (bumpers.Length > 0) { coinTransform.position = bumpers[Random.Range(0, bumpers.Length)].transform.position + Vector3.up; } } private void OnTriggerExit(Collider other) { if (other.CompareTag("Coin")) { Rigidbody rb = other.GetComponent<Rigidbody>(); if (rb != null) { rb.useGravity = true; } } } }